-- =============================================================================
-- REFERENCE DOCUMENTATION — NOT AN EXECUTABLE MIGRATION
-- -----------------------------------------------------------------------------
-- This file documents the production rollout strategy for the hybrid PK
-- migration. The dev/CI migration is generated by `prisma migrate dev` from
-- `schema.prisma` and lives under `prisma/migrations/`. Do not run this file
-- as a migration script; treat it as the runbook a team would adapt when
-- migrating a live database with real data.
-- =============================================================================

-- =============================================================================
-- Hybrid Primary Key Migration
-- -----------------------------------------------------------------------------
-- Migrates every PK from `String @default(cuid())` to a per-table strategy:
--
--   Tier A (UUIDv7, time-sortable, 16 bytes):
--     users, organizations, appointment_types, bookable_persons,
--     bookable_resources
--
--   Tier B (BigInt + publicId CUID): appointments, payments
--   Tier C (BigInt only):            otp_verifications, password_resets,
--                                    refresh_tokens, schedules, schedule_rules,
--                                    booking_questions, appointment_reschedules,
--                                    notifications, audit_logs, slot_locks,
--                                    appointment_type_entities
--   Tier D (composite natural key):  appointment_answers
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Required Postgres extensions
-- -----------------------------------------------------------------------------

-- pg_uuidv7 provides the `uuidv7()` SQL function used as the column default
-- on every Tier A id column. It returns a time-sortable UUID so new rows
-- cluster at the right edge of the B-tree, avoiding the random-insert page
-- splits that plagued cuid() / uuidv4 PKs.
CREATE EXTENSION IF NOT EXISTS pg_uuidv7;

-- pgcrypto is used as a fallback only if a deployment cannot install
-- pg_uuidv7 (e.g. RDS without the extension allowlisted). If pg_uuidv7 is
-- available, this line is harmless; if it is not, swap the column default
-- in the schema to `gen_random_uuid()` and accept the loss of time ordering.
CREATE EXTENSION IF NOT EXISTS pgcrypto;


-- =============================================================================
-- ZERO-DOWNTIME EXPAND-CONTRACT ROLLOUT
-- -----------------------------------------------------------------------------
-- Prisma's `prisma migrate` cannot execute this migration safely against a
-- live database because it would (a) DROP every existing FK, (b) ALTER every
-- PK column type in place, and (c) require an exclusive lock on every table
-- simultaneously. The strategy below splits the work into five phases so
-- writes never stop and readers never see a half-migrated row.
--
-- Run each phase as its own deploy. Do NOT collapse them.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- PHASE 1 — EXPAND: add new id columns alongside old ones
-- -----------------------------------------------------------------------------
-- For every Tier A table:
--   ALTER TABLE users ADD COLUMN id_new uuid DEFAULT uuidv7();
--   UPDATE users SET id_new = uuidv7() WHERE id_new IS NULL;  -- batched
--   ALTER TABLE users ALTER COLUMN id_new SET NOT NULL;
--   CREATE UNIQUE INDEX CONCURRENTLY users_id_new_key ON users (id_new);
--
-- For every Tier B / C table:
--   ALTER TABLE appointments ADD COLUMN id_new bigint
--     GENERATED BY DEFAULT AS IDENTITY;
--   -- backfill id_new in batches; identity sequence will populate new rows.
--   ALTER TABLE appointments ADD COLUMN public_id text;       -- Tier B only
--   UPDATE appointments SET public_id = <cuid()> WHERE public_id IS NULL;
--   CREATE UNIQUE INDEX CONCURRENTLY appointments_id_new_key
--     ON appointments (id_new);
--   CREATE UNIQUE INDEX CONCURRENTLY appointments_public_id_key
--     ON appointments (public_id);                            -- Tier B only
--
-- For every FK column referencing a migrated parent:
--   ALTER TABLE bookable_persons ADD COLUMN organization_id_new uuid;
--   ALTER TABLE appointment_reschedules ADD COLUMN appointment_id_new bigint;
--
-- No constraints, no NOT NULL, no FKs yet. Application code is unchanged.

-- -----------------------------------------------------------------------------
-- PHASE 2 — DUAL-WRITE: backfill FKs and start writing both old + new ids
-- -----------------------------------------------------------------------------
-- 2a. Backfill new FK columns by joining through the parent's id <-> id_new
--     mapping. Run in batches of ~10k rows to avoid long locks:
--
--       UPDATE bookable_persons bp
--       SET organization_id_new = o.id_new
--       FROM organizations o
--       WHERE bp.organization_id = o.id
--         AND bp.organization_id_new IS NULL
--         AND bp.id IN (SELECT id FROM bookable_persons
--                       WHERE organization_id_new IS NULL LIMIT 10000);
--
-- 2b. Deploy application code that writes BOTH the old and the new id/FK
--     columns on insert and on update of FK references. Reads still use the
--     old columns. This is the critical "expand" deploy — every write path
--     must be touched.
--
-- 2c. Add deferred FKs on the new columns so referential integrity holds
--     for newly written rows without blocking the backfill:
--
--       ALTER TABLE bookable_persons
--         ADD CONSTRAINT bookable_persons_organization_id_new_fkey
--         FOREIGN KEY (organization_id_new)
--         REFERENCES organizations (id_new)
--         DEFERRABLE INITIALLY DEFERRED;

-- -----------------------------------------------------------------------------
-- PHASE 3 — CUTOVER: swap reads to new columns
-- -----------------------------------------------------------------------------
-- 3a. Verify backfill is complete:
--       SELECT count(*) FROM bookable_persons WHERE organization_id_new IS NULL;
--     Must return 0 for every (table, fk) pair before continuing.
--
-- 3b. Inside one short transaction per table, rotate the column names so the
--     new column becomes the canonical id / FK. Wrap the whole rotation set
--     in a single transaction if your migration tool can handle it:
--
--       BEGIN;
--       ALTER TABLE users DROP CONSTRAINT users_pkey;
--       ALTER TABLE users RENAME COLUMN id     TO id_old;
--       ALTER TABLE users RENAME COLUMN id_new TO id;
--       ALTER TABLE users ADD PRIMARY KEY (id);
--       -- repeat the analogous rename for every dependent FK column
--       COMMIT;
--
-- 3c. Deploy application code that reads from the new columns. Old columns
--     are still being written to as a safety net.

-- -----------------------------------------------------------------------------
-- PHASE 4 — STOP DUAL-WRITE
-- -----------------------------------------------------------------------------
-- 4a. Deploy application code that no longer writes to the old columns. At
--     this point the codebase matches schema.prisma exactly.
--
-- 4b. Soak for at least one full backup cycle. If anything goes wrong, the
--     old columns still hold the last-known mapping and a rollback deploy
--     can flip reads back.

-- -----------------------------------------------------------------------------
-- PHASE 5 — CONTRACT: drop old columns
-- -----------------------------------------------------------------------------
-- After the soak window:
--
--   ALTER TABLE bookable_persons DROP COLUMN organization_id_old;
--   ALTER TABLE users             DROP COLUMN id_old;
--   -- ... and so on for every table touched in phase 3.
--
-- For appointment_answers (Tier D), the contract step also drops the old
-- synthetic `id` column and promotes the natural composite to PK:
--
--   ALTER TABLE appointment_answers DROP CONSTRAINT appointment_answers_pkey;
--   ALTER TABLE appointment_answers DROP COLUMN id;
--   ALTER TABLE appointment_answers
--     ADD PRIMARY KEY (appointment_id, question_id);
--
-- The schema is now fully aligned with schema.prisma and Prisma's diff will
-- report a clean state. Run `prisma db pull` followed by `prisma generate`
-- on a staging environment to confirm.
